#!/usr/bin/env bash
#
# nexum-bridge-recovery-restore.sh
# =============================================================================
# FIX the bridge "stuck In progress after refresh" regression by restoring the
# pre-cleanup recovery-safe behavior. Reverses ONLY the two bridge row-handling
# changes the earlier cleanup made; nothing else.
#
# ROOT CAUSE: the cleanup moved DB-row creation to the burn step and added a
# history filter hiding rows without a burn_tx. If the browser refreshed between
# the burn firing on-chain and its tx hash being saved, the row was left as
# 'burning' with burn_tx=null - which the completion path skips (it needs
# burn_tx to fetch the CCTP attestation) AND the filter hid. Result: burned
# funds with no way to finish the mint.
#
# THIS RESTORES:
#   1. nexum-web/hooks/useBridge.ts - create the DB row BEFORE approve again, so
#      a real bridge always has a record to attach its burn tx to.
#   2. nexum-web/components/bridge/BridgeHistory.tsx - show ALL rows; never hide
#      an in-flight row for lacking a burn_tx, so it stays visible/recoverable.
#
# NOTE (honest limit): this minimizes the refresh window and keeps rows
# recoverable (the behavior you had before), but no client-only flow is 100%
# refresh-proof. A backend burn-scanner would fully close it - not included.
#
# NO redeploy, NO contract change. Frontend only.
#
# DELIVERY: base64 heredoc; decode + sha256 verify before replace; backup once
#   per file per run; idempotent; --revert to pre-restore state.
#
# VERIFY AFTER: cd nexum-web && rm -rf .next && npx tsc --noEmit && npm run build
# =============================================================================
set -euo pipefail
find_root() { local d="$PWD"; while [ "$d" != "/" ]; do [ -d "$d/nexum-web/hooks" ] && { echo "$d"; return; }; d="$(dirname "$d")"; done; [ -d "$HOME/AfriFX/Nexum-main/nexum-web/hooks" ] && { echo "$HOME/AfriFX/Nexum-main"; return; }; [ -d "$HOME/AfriFX/nexum-web/hooks" ] && { echo "$HOME/AfriFX"; return; }; return 1; }
ROOT="$(find_root)" || { echo "ERROR: repo root not found (needs nexum-web/hooks)."; exit 1; }
echo "Repo root: $ROOT"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP_DIR="$ROOT/.nexum-bridge-recovery-backups"
UB_PATH="$ROOT/nexum-web/hooks/useBridge.ts";                  UB_SHA="41423ac4d676f8b8f21ccd5c8a287648ea1f5e8fb837810930b11f44ed6a1bdb"; UB_B64=""
BH_PATH="$ROOT/nexum-web/components/bridge/BridgeHistory.tsx"; BH_SHA="bc8bf76c28bf15e553cc01af4f41956504d87c8924f987dd038d91c466536402"; BH_B64=""
restore_edit() { local base="$1" dest="$2" p; p="$(ls -1tr "$BACKUP_DIR"/"$base".* 2>/dev/null | head -n1 || true)"; if [ -n "${p:-}" ] && [ -f "$p" ]; then cp -f "$p" "$dest" && echo "restored $base"; else echo "no backup for $base"; fi; }
revert() { echo "== REVERT =="; restore_edit "useBridge.ts" "$UB_PATH"; restore_edit "BridgeHistory.tsx" "$BH_PATH"; rm -f "$BACKUP_DIR"/*.* 2>/dev/null || true; rmdir "$BACKUP_DIR" 2>/dev/null || true; echo "revert complete."; }
if [ "${1:-}" = "--revert" ]; then revert; exit 0; fi
mkdir -p "$BACKUP_DIR"
write_edit() {
  local name="$1" path="$2" sha="$3" b64="$4"; local tmp; tmp="$(mktemp)"
  printf '%s' "$b64" | base64 -d > "$tmp" || { echo "ERROR decode $name"; rm -f "$tmp"; exit 1; }
  local got; got="$(sha256sum "$tmp" | cut -d' ' -f1)"
  [ "$got" = "$sha" ] || { echo "ERROR: checksum mismatch $name"; echo "  expected $sha"; echo "  got      $got"; rm -f "$tmp"; exit 1; }
  echo "  verified $name (sha256 ok)"
  [ -f "$path" ] && [ ! -f "$BACKUP_DIR/$(basename "$path").$STAMP" ] && cp -f "$path" "$BACKUP_DIR/$(basename "$path").$STAMP" && echo "  backed up $name"
  mv -f "$tmp" "$path"; echo "  wrote $path"
}
echo "== RESTORE bridge recovery-safe behavior =="
write_edit "useBridge.ts"      "$UB_PATH" "$UB_SHA" "$UB_B64"
write_edit "BridgeHistory.tsx" "$BH_PATH" "$BH_SHA" "$BH_B64"
echo
echo "== DONE =="
echo "Verify: cd $ROOT/nexum-web && rm -rf .next && npx tsc --noEmit && npm run build"
echo "Revert: bash $(basename "$0") --revert"
